def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    coords = sorted({x for op in ops for x in (op[1], op[2] + 1)})
    index = {x: i for i, x in enumerate(coords)}
    size = len(coords) - 1
    inf = 10**10

    minimum = [0] * (4 * size + 4)
    second = [inf] * (4 * size + 4)
    cleared = bytearray(4 * size + 4)

    def clear(node):
        minimum[node] = 0
        second[node] = inf
        cleared[node] = 1

    def push(node):
        left = node * 2
        right = left + 1
        if cleared[node]:
            clear(left)
            clear(right)
            cleared[node] = 0
        value = minimum[node]
        if minimum[left] < value:
            minimum[left] = value
        if minimum[right] < value:
            minimum[right] = value

    def pull(node):
        left = node * 2
        right = left + 1
        a, b = minimum[left], minimum[right]
        if a == b:
            minimum[node] = a
            second[node] = min(second[left], second[right])
        elif a < b:
            minimum[node] = a
            second[node] = min(second[left], b)
        else:
            minimum[node] = b
            second[node] = min(a, second[right])

    def update(node, start, end, ql, qr, colour):
        if ql <= start and end <= qr:
            if colour == 0:
                clear(node)
                return
            if colour <= minimum[node]:
                return
            if colour < second[node]:
                minimum[node] = colour
                return

        if colour and colour <= minimum[node]:
            return

        push(node)
        mid = (start + end) // 2
        if ql < mid:
            update(node * 2, start, mid, ql, qr, colour)
        if mid < qr:
            update(node * 2 + 1, mid, end, ql, qr, colour)
        pull(node)

    for op in ops:
        left = index[op[1]]
        right = index[op[2] + 1]
        colour = op[3] if op[0] else 0
        update(1, 0, size, left, right, colour)

    counts = {}

    def collect(node, start, end):
        if second[node] == inf:
            colour = minimum[node]
            if colour:
                counts[colour] = counts.get(colour, 0) + coords[end] - coords[start]
            return
        push(node)
        mid = (start + end) // 2
        collect(node * 2, start, mid)
        collect(node * 2 + 1, mid, end)

    collect(1, 0, size)
    return [[colour, counts[colour]] for colour in sorted(counts)]
